/* Hidden attribute reset */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #0f172a;
  --color-surface: #1e293b;
  --color-primary: #10b981;
  --color-primary-dark: #059669;
  --color-accent: #f59e0b;
  --color-danger: #ef4444;
  --color-text: #f8fafc;
  --color-text-dim: #94a3b8;
  --color-screen: #022c22;
  --color-digit: #34d399;
  --font-stack: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-stack);
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: 
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 16px 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
}

.timer-card {
  background-color: var(--color-surface);
  border: 4px solid var(--color-text);
  box-shadow: 6px 6px 0px #000000;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px dashed var(--color-text-dim);
  padding-bottom: 12px;
}

.title {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.led-indicator {
  width: 14px;
  height: 14px;
  border: 2px solid var(--color-text);
  background-color: #334155;
  transition: background-color 0.15s ease;
}

.led-indicator.active {
  background-color: var(--color-primary);
  box-shadow: 0 0 8px var(--color-primary);
}

.display-frame {
  background-color: var(--color-screen);
  border: 4px solid #000000;
  box-shadow: inset 3px 3px 0px rgba(0, 0, 0, 0.7);
  padding: 18px 12px;
  text-align: center;
}

.time-screen {
  font-size: 2.8rem;
  font-weight: 900;
  color: var(--color-digit);
  letter-spacing: 3px;
  text-shadow: 0 0 6px rgba(52, 211, 153, 0.5);
  user-select: none;
}

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 10px;
}

.btn {
  font-family: var(--font-stack);
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 6px;
  text-transform: uppercase;
  cursor: pointer;
  border: 3px solid #000000;
  box-shadow: 3px 3px 0px #000000;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
  outline: none;
}

.btn:hover:not(:disabled) {
  filter: brightness(1.1);
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px #000000;
}

.btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #000000;
}

.btn-primary.running {
  background-color: var(--color-accent);
}

.btn-secondary {
  background-color: var(--color-text);
  color: #000000;
}

.btn-danger {
  background-color: var(--color-danger);
  color: #ffffff;
}

.laps-section {
  border: 3px solid #000000;
  background-color: rgba(15, 23, 42, 0.6);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.laps-header {
  display: grid;
  grid-template-columns: 60px 1fr 1fr;
  font-weight: bold;
  font-size: 0.85rem;
  color: var(--color-text-dim);
  border-bottom: 2px solid var(--color-text-dim);
  padding-bottom: 6px;
}

.laps-header span:not(:first-child) {
  text-align: right;
}

.laps-list {
  list-style: none;
  max-height: 200px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-right: 4px;
}

.laps-list::-webkit-scrollbar {
  width: 6px;
}

.laps-list::-webkit-scrollbar-thumb {
  background-color: var(--color-text-dim);
  border: 1px solid #000000;
}

.lap-item {
  display: grid;
  grid-template-columns: 60px 1fr 1fr;
  padding: 6px 8px;
  background-color: rgba(255, 255, 255, 0.05);
  border-left: 4px solid transparent;
  font-size: 0.95rem;
}

.lap-item span:not(:first-child) {
  text-align: right;
}

.lap-item.fastest {
  background-color: rgba(16, 185, 129, 0.15);
  border-left: 4px solid var(--color-primary);
  color: var(--color-digit);
  font-weight: bold;
}

.fastest-badge {
  font-size: 0.75rem;
  margin-left: 4px;
  color: var(--color-primary);
}

.empty-laps-msg {
  text-align: center;
  color: var(--color-text-dim);
  font-size: 0.85rem;
  padding: 12px 0;
}

@media (max-width: 360px) {
  .time-screen {
    font-size: 2.2rem;
    letter-spacing: 2px;
  }
  .btn {
    font-size: 0.85rem;
    padding: 10px 4px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let startTime = 0;
  let accumulatedTime = 0;
  let timerInterval = null;
  let isRunning = false;
  let laps = []; // Array of { lapNumber, lapDuration, totalTime }

  const timeDisplay = document.getElementById('timeDisplay');
  const btnStartStop = document.getElementById('btnStartStop');
  const btnLap = document.getElementById('btnLap');
  const btnReset = document.getElementById('btnReset');
  const statusLed = document.getElementById('statusLed');
  const lapsList = document.getElementById('lapsList');
  const emptyMsg = document.getElementById('emptyMsg');

  function formatTime(ms) {
    const totalTenths = Math.floor(ms / 100);
    const tenths = totalTenths % 10;
    const totalSeconds = Math.floor(totalTenths / 10);
    const seconds = totalSeconds % 60;
    const minutes = Math.floor(totalSeconds / 60);

    const mm = String(minutes).padStart(2, '0');
    const ss = String(seconds).padStart(2, '0');
    return `${mm}:${ss}.${tenths}`;
  }

  function getCurrentTotalElapsed() {
    if (isRunning) {
      return accumulatedTime + (Date.now() - startTime);
    }
    return accumulatedTime;
  }

  function updateDisplay() {
    timeDisplay.textContent = formatTime(getCurrentTotalElapsed());
  }

  function startTimer() {
    isRunning = true;
    startTime = Date.now();
    btnStartStop.textContent = 'STOP';
    btnStartStop.classList.add('running');
    btnStartStop.setAttribute('aria-label', 'Stop Timer');
    btnLap.disabled = false;
    statusLed.classList.add('active');

    timerInterval = setInterval(updateDisplay, 50);
  }

  function stopTimer() {
    isRunning = false;
    accumulatedTime += Date.now() - startTime;
    clearInterval(timerInterval);
    timerInterval = null;
    btnStartStop.textContent = 'START';
    btnStartStop.classList.remove('running');
    btnStartStop.setAttribute('aria-label', 'Start Timer');
    btnLap.disabled = true;
    statusLed.classList.remove('active');
    updateDisplay();
  }

  function toggleStartStop() {
    if (isRunning) {
      stopTimer();
    } else {
      startTimer();
    }
  }

  function recordLap() {
    if (!isRunning) return;

    const currentTotal = getCurrentTotalElapsed();
    const previousTotal = laps.reduce((acc, lap) => acc + lap.lapDuration, 0);
    const lapDuration = currentTotal - previousTotal;
    const lapNumber = laps.length + 1;

    laps.unshift({
      lapNumber,
      lapDuration,
      totalTime: currentTotal
    });

    renderLaps();
  }

  function renderLaps() {
    lapsList.innerHTML = '';

    if (laps.length === 0) {
      emptyMsg.removeAttribute('hidden');
      return;
    }

    emptyMsg.setAttribute('hidden', '');

    let minDuration = Infinity;
    laps.forEach(lap => {
      if (lap.lapDuration < minDuration) {
        minDuration = lap.lapDuration;
      }
    });

    laps.forEach(lap => {
      const isFastest = laps.length > 1 && lap.lapDuration === minDuration;
      const li = document.createElement('li');
      li.className = 'lap-item' + (isFastest ? ' fastest' : '');

      const lapNumSpan = document.createElement('span');
      lapNumSpan.textContent = `#${String(lap.lapNumber).padStart(2, '0')}`;

      const splitSpan = document.createElement('span');
      splitSpan.textContent = formatTime(lap.lapDuration);
      if (isFastest) {
        const badge = document.createElement('span');
        badge.className = 'fastest-badge';
        badge.textContent = '★';
        badge.setAttribute('title', 'Fastest Lap');
        splitSpan.appendChild(badge);
      }

      const totalSpan = document.createElement('span');
      totalSpan.textContent = formatTime(lap.totalTime);

      li.appendChild(lapNumSpan);
      li.appendChild(splitSpan);
      li.appendChild(totalSpan);
      lapsList.appendChild(li);
    });
  }

  function resetTimer() {
    if (isRunning) {
      stopTimer();
    }
    accumulatedTime = 0;
    startTime = 0;
    laps = [];
    btnLap.disabled = true;
    updateDisplay();
    renderLaps();
  }

  btnStartStop.addEventListener('click', toggleStartStop);
  btnLap.addEventListener('click', recordLap);
  btnReset.addEventListener('click', resetTimer);

  document.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'BUTTON') return;
    if (e.code === 'Space') {
      e.preventDefault();
      toggleStartStop();
    } else if (e.code === 'KeyL') {
      e.preventDefault();
      if (!btnLap.disabled) recordLap();
    } else if (e.code === 'KeyR') {
      e.preventDefault();
      resetTimer();
    }
  });

  updateDisplay();
  renderLaps();
});
